import { test, expect } from '@playwright/test';

test.describe('Card Decline Error Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
    await expect(page.getByRole('heading', { name: /checkout/i })).toBeVisible();
  });

  test('should display error message when card is declined', async ({ page }) => {
    // Fill in customer information
    await page.getByLabel(/email/i).fill('test@example.com');
    await page.getByLabel(/full name/i).fill('John Doe');

    // Fill in address information
    await page.getByLabel(/street address/i).fill('123 Main St');
    await page.getByLabel(/city/i).fill('New York');
    await page.getByLabel(/state/i).fill('NY');
    await page.getByLabel(/zip code/i).fill('10001');

    // Fill in card details with declined card number
    await page.getByLabel(/card number/i).fill('4000000000000002');
    await page.getByLabel(/expiration date/i).fill('12/25');
    await page.getByLabel(/cvv/i).fill('123');

    // Submit the payment form
    await page.getByRole('button', { name: /pay|submit|complete purchase/i }).click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/card.*declined|payment.*failed|declined/i);
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/declined/i);
  });

  test('should show specific decline reason in error message', async ({ page }) => {
    // Fill in customer information
    await page.getByLabel(/email/i).fill('customer@example.com');
    await page.getByLabel(/full name/i).fill('Jane Smith');

    // Fill in address information
    await page.getByLabel(/street address/i).fill('456 Oak Ave');
    await page.getByLabel(/city/i).fill('Los Angeles');
    await page.getByLabel(/state/i).fill('CA');
    await page.getByLabel(/zip code/i).fill('90001');

    // Fill in card details with declined card
    await page.getByLabel(/card number/i).fill('4000000000000002');
    await page.getByLabel(/expiration date/i).fill('06/26');
    await page.getByLabel(/cvv/i).fill('456');

    // Submit the payment form
    await page.getByRole('button', { name: /pay|submit|complete purchase/i }).click();

    // Verify specific error details are shown
    const errorContainer = page.getByRole('alert');
    await expect(errorContainer).toBeVisible();

    // Check that error message contains relevant information
    const errorText = await errorContainer.textContent();
    expect(errorText).toBeTruthy();
    expect(errorText?.toLowerCase()).toMatch(/declined|error|failed/);
  });

  test('should allow user to retry after card decline', async ({ page }) => {
    // Fill in customer information
    await page.getByLabel(/email/i).fill('retry@example.com');
    await page.getByLabel(/full name/i).fill('Bob Johnson');

    // Fill in address information
    await page.getByLabel(/street address/i).fill('789 Pine Rd');
    await page.getByLabel(/city/i).fill('Chicago');
    await page.getByLabel(/state/i).fill('IL');
    await page.getByLabel(/zip code/i).fill('60601');

    // First attempt with declined card
    await page.getByLabel(/card number/i).fill('4000000000000002');
    await page.getByLabel(/expiration date/i).fill('03/27');
    await page.getByLabel(/cvv/i).fill('789');

    await page.getByRole('button', { name: /pay|submit|complete purchase/i }).click();

    // Verify error is shown
    await expect(page.getByText(/declined/i)).toBeVisible();

    // Clear the card field and enter a valid card
    await page.getByLabel(/card number/i).clear();
    await page.getByLabel(/card number/i).fill('4242424242424242');

    // Retry payment
    await page.getByRole('button', { name: /pay|submit|complete purchase/i }).click();

    // Verify success message appears (or redirect to success page)
    const successIndicator = page.getByText(/success|thank you|order.*confirmed/i);
    await expect(successIndicator).toBeVisible({ timeout: 5000 });
  });
});
